std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> cols(cols_);
    std::iota(cols.begin(), cols.end(), static_cast<std::size_t>(0));
    std::vector<double> result(cols_, 0.0);
    std::transform(cols.begin(), cols.end(), result.begin(),
        [this](std::size_t c) {
            std::vector<std::size_t> rows(rows_);
            std::iota(rows.begin(), rows.end(), static_cast<std::size_t>(0));
            return std::accumulate(rows.begin(), rows.end(), 0.0,
                [this, c](double s, std::size_t r) { return s + at(r, c); });
        });
    return result;
}

